DO $$
DECLARE
    r RECORD;
    fan_count INT := 0;
BEGIN
    RAISE NOTICE '=== TOP USERS: IDOL SUPERFANS ===';
    RAISE NOTICE '';
    RAISE NOTICE 'An Idol Superfan is a fan who is BOTH a Whale Fan (FMI > 20) AND an Event Enthusiast (EPS > 25).';
    RAISE NOTICE '';

    FOR r IN
        WITH fan_fmi AS (
            SELECT 
                i.interact_fan_pivot AS fan_id,
                ROUND(CAST(SUM((i.gift_metrics->>'Gift_Val_Usd')::numeric) / NULLIF(SUM(i.sess_dur_min), 0) AS numeric), 2) AS fmi
            FROM interactions i
            GROUP BY i.interact_fan_pivot
        ),
        fan_eps AS (
            SELECT 
                m.member_fan_pivot AS fan_id,
                ((e.evt_participation->>'On_Evt_Att')::int * 1) + 
                ((e.evt_participation->>'Off_Evt_Att')::int * 1.5) + 
                ((e.evt_participation->>'Meet_Att')::int * 2) AS eps
            FROM membershipandspending m
            JOIN eventsandclub e ON m.member_reg = e.events_member_pivot
        )
        SELECT DISTINCT
            f.user_registry,
            f.nick_label,
            ff.fmi,
            fe.eps
        FROM fans f
        JOIN fan_fmi ff ON f.user_registry = ff.fan_id
        JOIN fan_eps ee ON f.user_registry = ee.fan_id
        WHERE ff.fmi > 20 AND fe.eps > 25
        ORDER BY ff.fmi DESC
    LOOP
        fan_count := fan_count + 1;
        RAISE NOTICE 'Fan #%s: % (User: %)', fan_count, r.nick_label, r.user_registry;
        RAISE NOTICE '  FMI: %, EPS: %', r.fmi, r.eps;
    END LOOP;

    RAISE NOTICE '';
    RAISE NOTICE 'Total Idol Superfans found: %', fan_count;
END $$;

